+function convertWikiLinks(text: string, options: LinkStyleOptions): string {
+  return text.replace(/(!)?\\[\\[([^\\]\\r\
]+)\\]\\]/g, (match, embed: string | undefined, contents: string) => {
+    const image = embed === '!';
+    if ((image && options.imageStyle !== 'markdown') || (!image && options.linkStyle !== 'markdown')) {
+      return match;
+    }
+
+    const separator = contents.indexOf('|');
+    const target = separator === -1 ? contents : contents.slice(0, separator);
+    const display = separator === -1 ? undefined : contents.slice(separator + 1);
+    if (target.length === 0) {
+      return match;
+    }
+
+    if (image) {
+      const alt = display === undefined || isEmbedSize(display) ? target : display;
+      return `![${alt}](${target})`;
+    }
+
+    return `[${display ?? defaultHeadingDisplay(target)}](${target})`;
+  });
+}
+
+function convertMarkdownLinks(text: string, options: LinkStyleOptions): string {
+  let result = '';
+  let position = 0;
+
+  while (position < text.length) {
+    const markdownLink = parseMarkdownLink(text, position);
+    if (!markdownLink || (markdownLink.image ? options.imageStyle !== 'wiki' : options.linkStyle !== 'wiki') || markdownLink.target.includes('://')) {
+      result += text[position++];
+      continue;
+    }
+
+    const display = markdownLink.label;
+    const omitDisplay = markdownLink.image ? display.length === 0 || display === markdownLink.target : display === markdownLink.target || display === defaultHeadingDisplay(markdownLink.target);
+    result += markdownLink.image ? `![[${markdownLink.target}${omitDisplay ? '' : `|${display}`}]]` : `[[${markdownLink.target}${omitDisplay ? '' : `|${display}`}]]`;
+    position = markdownLink.end;
+  }
+
+  return result;
+}
+
+function parseMarkdownLink(text: string, start: number): MarkdownLink | null {
+  const image = text[start] === '!';
+  const labelStart = image ? start + 1 : start;
+  if (text[labelStart] !== '[' || isEscaped(text, labelStart)) {
+    return null;
+  }
+
+  const labelEnd = findBalancedClosingBracket(text, labelStart);
+  if (labelEnd === -1 || text[labelEnd + 1] !== '(') {
+    return null;
+  }
+
+  const parsedDestination = parseDestination(text, labelEnd + 2);
+  if (!parsedDestination) {
+    return null;
+  }
+
+  const label = text.slice(labelStart + 1, labelEnd);
+  const source = text.slice(start, parsedDestination.end);
+  if (label.includes('\
') || parsedDestination.raw.includes('\
') || source.includes('\\r')) {
+    return null;
+  }
+
+  return {end: parsedDestination.end, image, label: unescapeMarkdown(label), target: unescapeMarkdown(parsedDestination.target)};
+}
+
+function findBalancedClosingBracket(text: string, start: number): number {
+  let depth = 0;
+  for (let index = start; index < text.length; index++) {
+    if (isEscaped(text, index)) continue;
+    if (text[index] === '[') depth++;
+    if (text[index] === ']' && --depth === 0) return index;
+  }
+  return -1;
+}
+
+function parseDestination(text: string, start: number): {end: number, raw: string, target: string} | null {
+  let index = skipSpaces(text, start);
+  if (text[index] === '<') {
+    const targetStart = ++index;
+    while (index < text.length && (text[index] !== '>' || isEscaped(text, index))) index++;
+    if (text[index] !== '>') return null;
+    const target = text.slice(targetStart, index++);
+    index = skipSpaces(text, index);
+    return text[index] === ')' ? {end: index + 1, raw: text.slice(start, index + 1), target} : null;
+  }
+
+  const targetStart = index;
+  let depth = 0;
+  for (; index < text.length; index++) {
+    const character = text[index];
+    if (character === '\
' || character === '\\r') return null;
+    if (isEscaped(text, index)) continue;
+    if (character === '(') depth++;
+    if (character === ')') {
+      if (depth === 0) return {end: index + 1, raw: text.slice(start, index + 1), target: text.slice(targetStart, index)};
+      depth--;
+    }
+    if ((character === ' ' || character === '\	') && depth === 0) {
+      const destination = text.slice(targetStart, index);
+      index = skipSpaces(text, index);
+      return text[index] === ')' ? {end: index + 1, raw: text.slice(start, index + 1), target: destination} : null;
+    }
+  }
+  return null;
+}
+
+function skipSpaces(text: string, index: number): number {
+  while (text[index] === ' ' || text[index] === '\	') index++;
+  return index;
+}
+
+function isEscaped(text: string, index: number): boolean {
+  let count = 0;
+  for (let previous = index - 1; previous >= 0 && text[previous] === '\\\'; previous--) count++;
+  return count % 2 === 1;
+}
+
+function unescapeMarkdown(value: string): string {
+  return value.replace(/\\\\(.)/g, '$1');
+}
+
+function defaultHeadingDisplay(target: string): string {
+  const headingIndex = target.indexOf('#');
+  return headingIndex === -1 ? target : target.slice(0, headingIndex) ? `${target.slice(0, headingIndex)} > ${target.slice(headingIndex + 1)}` : target.slice(headingIndex + 1);
+}
+
+function isEmbedSize(display: string): boolean {
+  return /^\\d+(?:x\\d+)?$/.test(display) && (display === '300' || display === '300x200');
+}
